@include('v3.clinical.operations._styles')
<style>
  .cr-stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.cr-stat{display:flex;align-items:center;gap:12px;padding:15px 17px;border:1px solid #d5e5ec;border-radius:13px;background:#fff}.cr-stat i{display:grid;place-items:center;width:40px;height:40px;border-radius:11px;color:#087da7;background:#e1f5fa}.cr-stat strong{display:block;color:#103d5c;font-size:20px}.cr-stat span{color:#718b9e;font-size:11px}.cr-status{display:inline-flex;align-items:center;gap:5px;padding:5px 9px;border-radius:17px;color:#42647a;background:#edf4f7;font-size:10px;font-weight:800}.cr-status.is-complete{color:#137354;background:#e1f6ed}.cr-status.is-critical{color:#b52e3b;background:#fde8eb}.cr-status.is-cancelled{color:#7a4650;background:#f3e9eb}
  .cr-hospitals{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:20px}.cr-hospital{position:relative;display:flex;flex-direction:column;min-height:190px;padding:22px;border:1px solid #d4e5ed;border-radius:15px;background:linear-gradient(145deg,#fff,#f1fafc);transition:.2s}.cr-hospital:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(23,86,115,.12)}.cr-hospital__icon{display:grid;place-items:center;width:48px;height:48px;border-radius:13px;color:#fff;background:linear-gradient(135deg,#0b6d99,#15a7ab);font-size:21px}.cr-hospital h3{margin:16px 0 5px;color:#0d3d5c;font-size:18px;font-weight:800}.cr-hospital p{margin:0;color:#6f899a}.cr-hospital__meta{display:flex;gap:8px;margin-top:auto;padding-top:18px}.cr-hospital__meta span{padding:5px 9px;border-radius:16px;background:#e3f4f8;color:#276078;font-size:10px;font-weight:800}.cr-hospital .btn{margin-top:13px;border-radius:8px;font-weight:800}
  .cr-hospital--wide{grid-column:span 2}.cr-hospital__top{display:flex;align-items:center;gap:14px}.cr-hospital__top h3{margin:0 0 4px}.cr-room-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:16px}.cr-room{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid #d6e8ef;border-radius:11px;background:#fff;color:#164c69;transition:.18s}.cr-room:hover{border-color:#74c3d6;background:#f0fbfd;color:#087da7;text-decoration:none;transform:translateY(-1px)}.cr-room__icon{display:grid;place-items:center;flex:0 0 35px;height:35px;border-radius:9px;background:#e3f5f9;color:#0987a8}.cr-room__body{min-width:0;flex:1}.cr-room__body strong,.cr-room__body small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cr-room__body strong{font-size:12px}.cr-room__body small{margin-top:2px;color:#76909f;font-size:10px}.cr-room__count{padding:4px 7px;border-radius:12px;background:#eef6f8;color:#527487;font-size:9px;font-weight:800}.cr-room>i{font-size:10px;color:#8ea9b6}.cr-room-empty{grid-column:1/-1;padding:15px;border:1px dashed #c8dce5;border-radius:10px;color:#718b99;text-align:center}.cr-room-tabs{display:flex;flex-wrap:wrap;gap:8px;padding:0 18px 18px}.cr-room-tabs a{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border:1px solid #cfe1e9;border-radius:18px;background:#fff;color:#476b7f;font-size:11px;font-weight:800}.cr-room-tabs a:hover,.cr-room-tabs a.is-active{border-color:#128aaa;background:#128aaa;color:#fff;text-decoration:none}.cr-room-tabs a small{font-size:9px;opacity:.75}.cr-room-tabs a span{display:inline-grid;place-items:center;min-width:19px;height:19px;border-radius:10px;background:rgba(255,255,255,.22);font-size:9px}
  @media(max-width:900px){.cr-stat-grid,.cr-hospitals{grid-template-columns:repeat(2,1fr)}.cr-hospital--wide{grid-column:1/-1}}@media(max-width:600px){.cr-stat-grid,.cr-hospitals,.cr-room-list{grid-template-columns:1fr}.cr-hospital--wide{grid-column:auto}}
</style>
